UPDATE projects SET title='Markdown Podcast Studio', eyebrow='Notes into spoken episodes', summary='Turn Markdown and research notes into an editable two-host podcast or talk-show script, then render distinct local voices into an MP3. Download for Mac or Windows.', status='Desktop release · Mac + Windows', highlights_json='["Drafts an editable two-host conversation from source notes.","Renders distinct Kokoro voices locally and saves an MP3.","Also supports a single-narrator reading mode without an AI writer."]', scope='Can written notes become a useful spoken explanation while keeping the script editable?', ownership_json='["Built the Electron episode studio and source intake workflow.","Connected optional writing providers for conversation drafts.","Added local Kokoro voice rendering, MP3 output, and playback."]', systems_json='["Electron desktop app","Optional local or CLI writing providers","Kokoro voice synthesis and FFmpeg"]', note='Voice generation runs locally after the Kokoro model downloads. MP3 export needs FFmpeg; automatic drafting needs a separate writing provider. Builds are unsigned and unnotarized.', source_label='Downloads & setup', source_url='https://jakedoesdev.com/markdown-podcast-studio/', version=version+1, updated_at=CURRENT_TIMESTAMP WHERE id='markdown-podcast-narrator' AND version=1 AND archived_at IS NULL;

