UPDATE projects SET title='Stream DJ', eyebrow='AI broadcast studio', summary='A local-first desktop studio exploring audience requests, AI DJ voice, show programming, and audio playback for livestreams and radio-style shows.', status='Desktop release · Mac + Windows', highlights_json='["Plan reusable show blocks and review audience music requests.","Play local tracks with an on-air desk and optional AI DJ voice links.","Download a standalone Electron app for Apple Silicon, Intel Mac, or Windows."]', scope='What would a local-first, AI-assisted broadcast desk look like for an independent streamer?', ownership_json='["Built an Electron station workspace with on-air controls and a persistent player.","Explored DJ voice announcements, requests, and reusable programming blocks.","Separated music, text, and voice providers so the studio can evolve without one provider dependency."]', systems_json='["Electron desktop shell","React and TypeScript interface","Local backend and station data"]', note='Early desktop release. AI providers and streaming integrations require separate setup. Builds are unsigned and unnotarized; live broadcasting and audio routing need validation in your setup.', source_label='Downloads & setup', source_url='https://jakedoesdev.com/stream-dj/', version=version+1, updated_at=CURRENT_TIMESTAMP WHERE id='stream-dj' AND version=1 AND archived_at IS NULL;

